/* Stateful sample-and-hold decimation. Shared by worklet and numerical tests. */
(()=>{class LoFiDSP{constructor(bits=10,decimation=30){this.steps=2**(Math.max(2,Math.min(24,bits))-1);this.interval=1+Math.round(127*Math.max(0,Math.min(100,decimation))/100);this.phase=0;this.held=[]}process(input,output){const count=output[0]?.length||0;for(let i=0;i<count;i++){if(this.phase===0)for(let ch=0;ch<output.length;ch++){const x=input[ch]?.[i]??input[0]?.[i]??0;this.held[ch]=Math.round(Math.max(-1,Math.min(1,x))*this.steps)/this.steps}for(let ch=0;ch<output.length;ch++)output[ch][i]=this.held[ch]||0;this.phase=(this.phase+1)%this.interval}}}globalThis.PocketLoFiDSP=LoFiDSP})();
